import Model from "flarum/common/Model";
export default class Giveaway extends Model {
  slug() {
    return Model.attribute("slug").call(this);
  }
  title() {
    return Model.attribute("title").call(this);
  }
  prize() {
    return Model.attribute("prize").call(this);
  }
  status() {
    return Model.attribute("status").call(this);
  }
  endsAt() {
    return Model.attribute("endsAt", Model.transformDate).call(this);
  }
  drawnAt() {
    return Model.attribute("drawnAt", Model.transformDate).call(this);
  }
}
flarum.reg.add('ygpynet-giveaways', 'common/models/Giveaway', Giveaway);